Reference:
def steps_to_higher(readings: list[int]) -> list[int]:
    res = [0] * len(readings)
    stack = []  # indices whose readings are non-increasing
    for i, v in enumerate(readings):
        while stack and readings[stack[-1]] < v:
            j = stack.pop()
            res[j] = i - j
        stack.append(i)
    return res

